/** Run every scenario → rows { id, title, truth, engine, table, oracle, agree: { engine, table, oracle }, why } */
export async function runScenarios(deps, { only = null } = {}) {
  const rows = [];
  for (const sc of SCENARIOS) {
    if (only && !only.includes(sc.id)) continue;
    const s = new Sim({ fs, path, ...deps }, sc.world);
    let err = null;
    try { await sc.run(s); } catch (e) { err = String((e && e.stack) || e); }
    const j = s.judge();
    const t = sc.truth;
    const why = [];
    if (j.engine.ledger !== t.ledger) why.push(`engine ledger ${j.engine.ledger}≠${t.ledger}`);
    if (j.engine.block !== t.block) why.push(`engine block ${j.engine.block}≠${t.block}`);
    if (j.engine.verbs !== t.verbs) why.push(`engine verbs ${j.engine.verbs}≠${t.verbs}`);
    if (t.arms !== undefined && j.engine.arms !== t.arms) why.push(`engine arms ${j.engine.arms}≠${t.arms}`);
    if (t.said && !said(t.said)(j.engine.notices)) why.push(`engine never said ${t.said}`);
    if (t.noSaid && said(t.noSaid)(j.engine.notices)) why.push(`engine said ${t.noSaid}`);
    let extraOk = true; try { extraOk = t.extra ? !!t.extra(j, s) : true; } catch (e) { extraOk = false; }
    if (!extraOk) why.push('engine extra');
    const engineOk = why.length === 0;
    const tableOk = j.table.block === t.block && j.table.charges === t.ledger;
    if (!tableOk) why.push(`table block ${j.table.block}/charges ${j.table.charges}`);
    const oracleOk = j.oracle.block === t.block && j.oracle.consistent;
    if (!oracleOk) why.push(`oracle block ${j.oracle.block}${j.oracle.consistent ? '' : ' (charge≠went-out)'}`);
    if (err) why.push('threw: ' + err.split('\n')[0]);
    rows.push({ id: sc.id, title: sc.title, truth: t, engine: j.engine, table: j.table, oracle: j.oracle, agree: { engine: engineOk && !err, table: tableOk, oracle: oracleOk }, why, chain: j.engine.chain });
  }
  return rows;
}
